1	//! Sleeping and waking: the [`Wake`] trait a ring calls when one
2	//! side must wait for the other, and its two implementations.
3	//!
4	//! - The crate owns the protocol: which word a side sleeps on, the
5	//!   flag or count that says it sleeps, and the re-check after the
6	//!   flag, so a wake is never lost. A [`Wake`] implementation owns
7	//!   only the sleep and the wake, which are the platform's.
8	//! - [`NoWake`] spins and wakes nothing, so a ring over it compiles
9	//!   every wake check out, and its waits are polls.
10	//! - [`Futex`], on Linux, sleeps in the kernel on the word itself,
11	//!   shared between processes, with a timeout, since a peer can die
12	//!   while another sleeps.
13	//! - Every process attached to one ring uses the same
14	//!   implementation. A mismatch is not detected and costs latency
15	//!   only: a futex sleeper no one wakes returns at its timeout.
16	//! - `MpscRing` in `mpsc::v3` is the ring that takes one.
17	
18	use core::sync::atomic::{AtomicU32, Ordering};
19	
20	use crate::Deadline;
21	
22	/// `struct Seen` is a word and the value the word was last seen holding, read before the caller's
23	/// last look at what it waits for. A wait sleeps only while the word still holds that value.
24	///
25	/// - The value guards against a lost wake: the waker changes the word before it wakes, so a change
26	///   between the caller's look and its sleep makes the sleep return at once. The kernel compares
27	///   and sleeps as one step.
28	/// - A caller makes a `Seen` with [`Seen::load`], or with [`Seen::written`] when its own
29	///   read-modify-write put the value in the word.
30	pub struct Seen<'a> {
31	    word: &'a AtomicU32,
32	    value: u32,
33	}
34	
35	impl<'a> Seen<'a> {
36	    /// `Seen::load` reads the word with a `SeqCst` load, before the caller's look.
37	    pub fn load(word: &'a AtomicU32) -> Self {
38	        Seen {
39	            word,
40	            value: word.load(Ordering::SeqCst),
41	        }
42	    }
43	
44	    /// `Seen::written` records `value` as the word's value, when the caller's own read-modify-write
45	    /// wrote it there.
46	    pub fn written(word: &'a AtomicU32, value: u32) -> Self {
47	        Seen { word, value }
48	    }
49	
50	    /// `Seen::word` returns the word a wait sleeps on.
51	    pub fn word(&self) -> &'a AtomicU32 {
52	        self.word
53	    }
54	
55	    /// `Seen::value` returns the value the word was seen holding.
56	    pub fn value(&self) -> u32 {
57	        self.value
58	    }
59	}
60	
61	/// The platform's sleep and wake, called by a ring's waiting
62	/// paths.
63	pub trait Wake {
64	    /// Whether the waking side must look for sleepers: `false`
65	    /// compiles every wake check out of the message paths.
66	    const WAKES: bool;
67	
68	    /// `wait` sleeps while the word in `seen` still holds the value `seen` recorded.
69	    ///
70	    /// - `wait` returns on a wake, when the word no longer holds that value, spuriously, or at the
71	    ///   implementation's own timeout, and the caller looks again whichever it was.
72	    fn wait(seen: Seen<'_>);
73	
74	    /// `wait_until` sleeps while the word in `seen` still holds the value `seen` recorded, until
75	    /// `deadline` at the latest. The caller's deadline replaces the implementation's own timeout.
76	    ///
77	    /// - `wait_until` returns as [`wait`](Wake::wait) does, and at `deadline`. A sleep that returns
78	    ///   early sleeps again to the same deadline.
79	    fn wait_until(seen: Seen<'_>, deadline: Deadline);
80	
81	    /// Wake every sleeper on `word`.
82	    fn wake(word: &AtomicU32);
83	}
84	
85	/// No sleeping: a wait is one spin-loop hint and a wake does
86	/// nothing, so a waiting call polls.
87	pub struct NoWake;
88	
89	impl Wake for NoWake {
90	    const WAKES: bool = false;
91	
92	    fn wait(_seen: Seen<'_>) {
93	        core::hint::spin_loop();
94	    }
95	
96	    fn wait_until(_seen: Seen<'_>, _deadline: Deadline) {
97	        core::hint::spin_loop();
98	    }
99	
100	    fn wake(_word: &AtomicU32) {}
101	}
102	
103	/// A Linux futex on the word itself, shared between processes,
104	/// the sleep bounded by `TIMEOUT_MS` milliseconds.
105	///
106	/// - Not `FUTEX_PRIVATE_FLAG`: the word is in memory other
107	///   processes map, and the kernel keys the sleep by the page.
108	/// - The timeout is what turns a dead peer into a poll: a sleeper
109	///   no one wakes looks again every `TIMEOUT_MS`.
110	#[cfg(target_os = "linux")]
111	pub struct Futex<const TIMEOUT_MS: u32 = 10>;
112	
113	#[cfg(target_os = "linux")]
114	impl<const TIMEOUT_MS: u32> Wake for Futex<TIMEOUT_MS> {
115	    const WAKES: bool = true;
116	
117	    fn wait(seen: Seen<'_>) {
118	        // FUTEX_WAIT's timeout is relative.
119	        let timeout = libc::timespec {
120	            tv_sec: (TIMEOUT_MS / 1000) as libc::time_t,
121	            tv_nsec: ((TIMEOUT_MS % 1000) * 1_000_000) as libc::c_long,
122	        };
123	        futex_wait(seen, libc::FUTEX_WAIT, &timeout);
124	    }
125	
126	    fn wait_until(seen: Seen<'_>, deadline: Deadline) {
127	        // FUTEX_WAIT_BITSET's timeout is absolute, on CLOCK_MONOTONIC, the clock a Deadline is read
128	        // on, so no remaining time is computed. The divisors are constants, so the split into
129	        // seconds and nanoseconds costs multiplies, paid once before a sleep.
130	        let ns = deadline.monotonic_nanos();
131	        let at = libc::timespec {
132	            tv_sec: (ns / 1_000_000_000) as libc::time_t,
133	            tv_nsec: (ns % 1_000_000_000) as libc::c_long,
134	        };
135	        futex_wait(seen, libc::FUTEX_WAIT_BITSET, &at);
136	    }
137	
138	    fn wake(word: &AtomicU32) {
139	        // SAFETY: word is a live, aligned u32, and FUTEX_WAKE only
140	        // wakes sleepers keyed by its address, reading nothing.
141	        unsafe {
142	            libc::syscall(
143	                libc::SYS_futex,
144	                word.as_ptr(),
145	                libc::FUTEX_WAKE,
146	                i32::MAX,
147	                core::ptr::null::<libc::timespec>(),
148	                core::ptr::null::<u32>(),
149	                0u32,
150	            );
151	        }
152	    }
153	}
154	
155	/// `futex_wait` sleeps once on the word in `seen` while the word holds the value `seen` recorded.
156	/// `op` is `FUTEX_WAIT`, with `timeout` relative, or `FUTEX_WAIT_BITSET`, with `timeout` absolute
157	/// on `CLOCK_MONOTONIC`.
158	///
159	/// - The bitset is `FUTEX_BITSET_MATCH_ANY`, so the plain `FUTEX_WAKE` in [`Futex::wake`] wakes
160	///   either sleep.
161	#[cfg(target_os = "linux")]
162	fn futex_wait(seen: Seen<'_>, op: libc::c_int, timeout: &libc::timespec) {
163	    // SAFETY: the word is a live, aligned u32 for the call, which the kernel reads atomically
164	    // against the seen value, and the timeout is a valid timespec. FUTEX_WAIT ignores the last
165	    // argument. An error return (EAGAIN when the word moved, ETIMEDOUT, EINTR) is a return, and the
166	    // caller looks again.
167	    unsafe {
168	        libc::syscall(
169	            libc::SYS_futex,
170	            seen.word().as_ptr(),
171	            op,
172	            seen.value(),
