1	//! Single-threaded zc-ring-x1 mpsc v3 round-trip bench, policy
2	//! (`send`) API, the attachable segmented ring over a pool, generic
3	//! over the ring's segment mode and wake.
4	
5	use std::hint::black_box;
6	
7	use zc_ring_x1::mpsc::v3::{Mode, MpscConsumer, MpscProducer, Multi, Single};
8	use zc_ring_x1::policy;
9	use zc_ring_x1::wake::{Futex, NoWake, Wake};
10	
11	use crate::benches::zcr_common::{Msg, SEGMENTS, leak_mpsc_v3_ring, ring_switches};
12	use crate::harness::{self, Bench, RunCfg};
13	use crate::record;
14	use crate::report;
15	
16	/// Registry name used on the CLI.
17	pub const NAME: &str = "zcr-mpsc-v3-1t";
18	
19	/// Registry name of the `Multi` ring over one segment.
20	pub const NAME_1SEG: &str = "zcr-mpsc-v3-1t-1seg";
21	
22	/// Registry name of the `Single` ring.
23	pub const NAME_SINGLE: &str = "zcr-mpsc-v3-1t-single";
24	
25	/// Registry name of [`NAME`]'s ring over a futex wake.
26	pub const NAME_FUTEX: &str = "zcr-mpsc-v3-1t-futex";
27	
28	/// Registry name of [`NAME_1SEG`]'s ring over a futex wake.
29	pub const NAME_1SEG_FUTEX: &str = "zcr-mpsc-v3-1t-1seg-futex";
30	
31	/// Registry name of [`NAME_SINGLE`]'s ring over a futex wake.
32	pub const NAME_SINGLE_FUTEX: &str = "zcr-mpsc-v3-1t-single-futex";
33	
34	/// Same-thread round-trip sending through the v3 MPSC ring's
35	/// `send` and receiving through its consumer guard, the shape of
36	/// `zcr-mpsc-v2-1t` over the attachable ring.
37	///
38	/// - One message in flight, so the consumer keeps up and the ring
39	///   lives in its first segment: the measurement is v2's fast
40	///   path plus whatever v3's control block, counted roles, mode `M`,
41	///   and wake `W` cost on it. The switch counts are the run's
42	///   counters and should read zero.
43	/// - Every wait spins, so over a wake that can sleep nobody does,
44	///   and what `W` adds is its checks on the message path.
45	pub struct ZcrMpscV3OneThread<M: Mode, W: Wake> {
46	    producer: MpscProducer<'static, M, W>,
47	    consumer: MpscConsumer<'static, M, W>,
48	    counter: u64,
49	    title: &'static str,
50	}
51	
52	impl<M: Mode, W: Wake> ZcrMpscV3OneThread<M, W> {
53	    /// Construct the bench over one fresh leaked v3 MPSC ring of
54	    /// `segments` segments, reporting under `title`.
55	    pub fn new(segments: u32, title: &'static str) -> Self {
56	        let (producer, consumer) = leak_mpsc_v3_ring::<M, W>(segments);
57	        Self {
58	            producer,
59	            consumer,
60	            counter: 0,
61	            title,
62	        }
63	    }
64	
65	    /// Segment switches each end made, producer then consumer.
66	    pub fn switches(&self) -> (u64, u64) {
67	        (self.producer.switches(), self.consumer.switches())
68	    }
69	}
70	
71	impl<M: Mode, W: Wake> Bench for ZcrMpscV3OneThread<M, W> {
72	    fn name(&self) -> &str {
73	        self.title
74	    }
75	
76	    fn step(&mut self) -> u64 {
77	        self.counter = self.counter.wrapping_add(1);
78	        let c = self.counter;
79	        self.producer
80	            .send::<Msg>(policy::spin, |m| *m = c)
81	            // OK: the spin policy returns true forever, so the send
82	            // never gives up.
83	            .expect("spin policy never gives up");
84	        let slot = self
85	            .consumer
86	            .reserve_slot_with::<Msg>(policy::spin)
87	            // OK: as above, the policy never gives up.
88	            .expect("spin policy never gives up");
89	        let v = *slot;
90	        slot.release();
91	        black_box(v)
92	    }
93	}
94	
95	/// Run the bench over a ring of mode `M`, wake `W`, and `segments`
96	/// segments, reporting and recording under `name`.
97	pub fn run_as<M: Mode, W: Wake>(name: &str, title: &'static str, segments: u32, cfg: &RunCfg) {
98	    let mut bench = ZcrMpscV3OneThread::<M, W>::new(segments, title);
99	    let mut out = harness::run_adaptive(&mut bench, cfg);
100	    out.counters = ring_switches(bench.switches());
101	    report::print_report(bench.name(), &out, cfg);
102	    record::append(name, &out, cfg);
103	}
104	
105	/// Registry entry point: `Multi` over [`SEGMENTS`] segments with
106	/// no wake, v2's ring in v3.
107	pub fn run(cfg: &RunCfg) {
108	    run_as::<Multi, NoWake>(
109	        NAME,
110	        "zcr-mpsc-v3-1t: zc-ring-x1 mpsc v3 send round-trip (1 thread)",
111	        SEGMENTS,
112	        cfg,
113	    );
114	}
115	
116	/// Registry entry point: `Multi` over one segment with no wake,
117	/// `Single`'s geometry in the mode that can switch, so against
118	/// [`run_single`] the difference is the mode alone.
119	pub fn run_1seg(cfg: &RunCfg) {
120	    run_as::<Multi, NoWake>(
121	        NAME_1SEG,
122	        "zcr-mpsc-v3-1t-1seg: zc-ring-x1 mpsc v3 send round-trip, Multi over 1 segment (1 thread)",
123	        1,
124	        cfg,
125	    );
126	}
127	
128	/// Registry entry point: `Single`, one segment and no switch
129	/// compiled in, with no wake.
130	pub fn run_single(cfg: &RunCfg) {
131	    run_as::<Single, NoWake>(
132	        NAME_SINGLE,
133	        "zcr-mpsc-v3-1t-single: zc-ring-x1 mpsc v3 send round-trip, Single (1 thread)",
134	        1,
135	        cfg,
136	    );
137	}
138	
139	/// Registry entry point: [`run`]'s ring over a futex wake. Nobody
