/// `struct Ticks` is a duration: a count of ticks of the crate's monotonic clock, held in a `u64`.
///
/// - A send's `give_up`, `spin`, and `wait` are each a `Ticks`.
/// - A `Ticks` is not a point in time. A point in time is a [`Deadline`].
/// - A caller makes a `Ticks` with [`secs_to_ticks`], [`millis_to_ticks`], [`microsecs_to_ticks`], or
///   [`nanos_to_ticks`], once, when it sets up its times, so a send only adds and compares ticks
///   and never converts a unit.
/// - A tick is one nanosecond today. A later clock may count the CPU's own counter instead, and a
///   caller that makes its `Ticks` with the conversions does not change.
/// - `Ticks` lives in the crate core, as [`Full`] does, because the sends and the waits share it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Ticks(u64);

/// - `us`: the number of microseconds.
///
/// # Returns
///
/// - The same duration in ticks. A duration too long to count saturates to [`Ticks::FOREVER`].
pub fn microsecs_to_ticks(us: u64) -> Ticks {
    Ticks(us.saturating_mul(1_000))
}

        // `ends` holds the spin's end and the sleep's end, set at the first empty ring, so a
        // receive that finds a message reads no clock, and each later check is one reading and a
        // compare or two.
        let mut ends: Option<(u64, u64)> = None;
        self.recv_at(
            |_, look| {
                if spin_time == Ticks::FOREVER {
                    core::hint::spin_loop();
                    return true;
                }
                let now = now_ticks();
                let (spin_end, sleep_end) = *ends.get_or_insert_with(|| {
                    let spin_end = now.saturating_add(spin_time.0);
                    (spin_end, spin_end.saturating_add(sleep_time.0))
                });
                if now < spin_end {
                    core::hint::spin_loop();
                    return true;
                }
                let deadline = if sleep_time == Ticks::FOREVER {
                    None
                } else if now >= sleep_end {
                    return false;
                } else {
                    Some(Deadline::at(sleep_end))
                };
                look.sleep_empty(deadline);
                true
            },
            read_msg,
        )
    }

    /// `recv` takes the oldest message in the ring, asking `policy` what to do each time it finds
    /// the ring empty: look again, sleep first, or give up with `Err(Empty)`. When a message is
    /// there, or arrives, `recv` calls `read_msg` with a reference to the message in its slot,

impl Spins for SpinOnly {}

/// `struct Sleep` is the choice that an endpoint of the ring spins for some time, which may be
/// none, then may sleep on `S`, such as [`Futex`], for some further time or forever.
///
/// - A ring over `Sleep<S>` offers `send_spin_sleep` and `recv_spin_sleep`. A spin alone on it
///   does not compile: an endpoint that only spins would pay for the checks that wake sleepers and
///   gain nothing, and [`SpinOrSleep`] is the choice that says so on purpose.
/// - Every endpoint checks for sleepers, a producer after each commit and the consumer at each half
///   segment of messages read, whether or not anyone sleeps.
/// - `S` must be a wake that sleeps. A `Sleep` over one that does not, such as [`NoWake`], fails to
///   compile where the ring is used.
pub struct Sleep<S: Wake>(PhantomData<S>);

impl<S: Wake> Wake for Sleep<S> {
    const WAKES: bool = {
        assert!(S::WAKES, "Sleep needs a wake that sleeps, such as Futex");
        true
    };
    const PROTOCOL: u32 = S::PROTOCOL;

    fn wait(seen: Seen<'_>) {
        S::wait(seen);
    }

    fn wait_until(seen: Seen<'_>, deadline: Deadline) {
        S::wait_until(seen, deadline);
    }

    fn wake(word: &AtomicU32) {
        S::wake(word);
    }
}

impl<S: Wake> Waits for Sleep<S> {}

impl<S: Wake> Sleeps for Sleep<S> {}

