/// Registry entry point: `Single` over `Sleep<Futex>`, each
/// receiver spinning for a microsecond before it sleeps. A round
/// trip is far under a microsecond, so the message arrives inside
/// the spin, and against [`run_sleep`] the difference is the sleep
/// and the wake a spin spares.
pub fn run_spin_sleep(cfg: &RunCfg) {
    let waiting = SpinSleep {
        spin: microsecs_to_ticks(1),
        sleep: Ticks::FOREVER,
    };
    run_as::<Single, Sleep<Futex>, _>(
        NAME_SPIN_SLEEP,
        "zcr-mpsc-v4-2t-single-st1us-wtfe-sleep-futex: zc-ring-x1 mpsc v4 send round-trip, Single, Sleep<Futex> (2 threads, spin 1 us then sleep)",
        waiting,
        cfg,
    );
}

/// Registry entry point: `Single` over `SpinOnly`, each receiver
/// spinning for a microsecond at a time. Against the twin that
/// spins without a limit the difference is the clock a timed spin
/// reads at each empty look.
pub fn run_timed_spin(cfg: &RunCfg) {
    let waiting = TimedSpin {
        give_up: microsecs_to_ticks(1),
    };
    run_as::<Single, SpinOnly, _>(
        NAME_TIMED_SPIN,
        "zcr-mpsc-v4-2t-single-st1us-wtnone: zc-ring-x1 mpsc v4 send round-trip, Single (2 threads, spin 1 us at a time)",
        waiting,
        cfg,
    );
}
