import importlib.util, sys
spec = importlib.util.spec_from_file_location("tables", "tmp/tables.py")
src = open("tmp/tables.py").read().replace("\nmain()\n", "\n")
mod = type(sys)("tables"); exec(compile(src, "tables.py", "exec"), mod.__dict__)
NAMES = {"3900x": "3900X", "7600x": "7600X", "rpi5-20cd": "Pi 5"}
_cache = {}
def rows(key):
    if key in _cache: return _cache[key]
    out = []
    pairs = mod.groups()[key]
    for host in mod.HOSTS:
        r, _, _ = mod.run(host, pairs)
        for label, a, b in pairs:
            for pl in mod.ORDER:
                x = r.get((a, b, pl))
                if x: out.append((NAMES[host], label, pl, float(x[0]), float(x[1]), float(x[2]), float(x[3]), x[5]))
    _cache[key] = out
    return out
def table(key, ha, hb):
    L = [f"| host | bench | placement | {ha} | {hb} | d% | claim% | verdict |", "|---|---|---|---|---|---|---|---|"]
    for h, label, pl, a, b, d, c, v in rows(key):
        ds = f"{d:+.2f}" if abs(d) >= 0.005 else "0.00"
        L.append(f"| {h} | `{label}` | {pl} | {a:.3f} | {b:.3f} | {ds} | {c:.2f} | {v} |")
    return "\n".join(L)
