import json,struct,zlib,subprocess
def zst(b): return len(subprocess.run(['zstd','-19','-c','-q'],input=b,capture_output=True).stdout)
CONST=('config','host','binary')
for h in ('3900x','7600x','rpi5-20cd'):
    f=f'records/mpsc-v4-{h}.jsonl'; raw=open(f,'rb').read()
    consts={}; strs={}; out=bytearray(); hoist=[]
    def sid(s):
        return strs.setdefault(s,len(strs))
    def enc(v):
        if isinstance(v,bool): out.append(v)
        elif isinstance(v,int):
            out.extend(struct.pack('<q',v) if abs(v)>=2**31 else struct.pack('<i',v))
        elif isinstance(v,float): out.extend(struct.pack('<d',v))
        elif isinstance(v,str): out.extend(struct.pack('<H',sid(v)))
        elif v is None: out.append(0)
        elif isinstance(v,list):
            out.extend(struct.pack('<H',len(v)))
            for x in v: enc(x)
        elif isinstance(v,dict):
            out.extend(struct.pack('<B',len(v)))
            for k,x in v.items(): out.extend(struct.pack('<H',sid(k))); enc(x)
    n=0
    for l in raw.splitlines():
        r=json.loads(l); n+=1
        key=json.dumps([r[k] for k in CONST],sort_keys=True)
        cid=consts.setdefault(key,len(consts))
        out.extend(struct.pack('<H',cid))
        rest={k:v for k,v in r.items() if k not in CONST}
        for k,v in rest.items(): enc(v)          # fixed schema: no key names per run
        rest['const']=cid; hoist.append(json.dumps(rest,separators=(',',':')))
    table=('\n'.join(consts)+'\n'+'\n'.join(strs)).encode()
    b=bytes(out)+table; hj=('\n'.join(consts)+'\n'+'\n'.join(hoist)).encode()
    print(f'{h}: runs {n} const-sets {len(consts)}')
    print(f'  jsonl today      raw {len(raw)/1e6:6.2f} MB  zlib {len(zlib.compress(raw,6))/1e6:5.2f}  zstd {zst(raw)/1e6:5.2f}')
    print(f'  jsonl, hoisted   raw {len(hj)/1e6:6.2f} MB  zlib {len(zlib.compress(hj,6))/1e6:5.2f}  zstd {zst(hj)/1e6:5.2f}')
    print(f'  binary, hoisted  raw {len(b)/1e6:6.2f} MB  zlib {len(zlib.compress(b,6))/1e6:5.2f}  zstd {zst(b)/1e6:5.2f}   ({len(out)/n:.0f} B/run, table {len(table)/1e3:.0f} kB)')
EOF

