1	//! Two-threaded zc-ring-x1 mpsc v4 round-trip benches whose
2	//! receivers wait by a timed form with a limit, where the twins in
3	//! `zcr_mpsc_v4_2t` spin without one: a sleep, a spin and then a
4	//! sleep, and a timed spin.
5	//!
6	//! Each registry name is
7	//! `zcr-mpsc-v4-<threads>-<mode>-st<spin>-wt<wait>[-<wait choice>]`:
8	//!
9	//! - Spin, `st`: how long a receiver spins at an empty ring before
10	//!   it waits, `0` being no spin and `1us` a microsecond.
11	//! - Wait, `wt`: how long it then waits, `fe` being forever, a
12	//!   sleep until a producer wakes it, and `none` no wait, the
13	//!   receive giving up and being made again.
14	//! - Wait choice: the ring's, nothing for `SpinOnly` and
15	//!   `sleep-futex` for `Sleep<Futex>`.
16	
17	use std::hint::black_box;
18	use std::thread;
19	
20	use zc_ring_x1::mpsc::v4::{Mode, MpscConsumer, MpscProducer, Single};
21	use zc_ring_x1::wake::{Futex, Sleep, Sleeps, SpinOnly, Spins, Waits};
22	use zc_ring_x1::{Ticks, microsecs_to_ticks};
23	
