import sys, re
sys.path.insert(0, 'tmp')
import tlib

def fmt(rows, ha, hb, relabel, keep=lambda lab: True):
    L = [f"| host | bench | placement | {ha} ns | {hb} ns | difference % |", "|---|---|---|---|---|---|"]
    for h, lab, pl, a, b, d, c, v in rows:
        if not keep(lab):
            continue
        ds = f"{d:+.2f}" if abs(d) >= 0.005 else "0.00"
        cell = f"{ds} ±{c:.2f}"
        if v != "detected":
            cell = f"({cell})"
        L.append(f"| {h} | `{relabel(lab)}` | {pl} | {a:.3f} | {b:.3f} | {cell} |")
    return L

def chk(lab): return lab.endswith(', checks')
def base(lab): return lab.replace(', checks', '')

def spec(note, sec, n):
    v4 = note == 'v4'
    so, sos = ('-so', '-sos-futex') if v4 else ('', '-futex')
    key = 'v4' if v4 else 'v3'
    field = lambda lab: f"..{base(lab)}-*-stfe-wtnone{sos if chk(lab) else so}"
    if sec == 'v4 against v3':
        r = tlib.rows('v3v4')
        if n == 1:
            return fmt(r, '`v3-..`', '`v4-..-so`', lambda l: f"{l}-stfe-wtnone", lambda l: not chk(l))
        return fmt(r, '`v3-..-futex`', '`v4-..-sos-futex`', lambda l: f"{base(l)}-stfe-wtnone", chk)
    if sec == 'Multi over one segment against two':
        return fmt(tlib.rows(key + '-segs'), '`multi-2seg`', '`multi-1seg`', field)
    if sec == 'Single against Multi over one segment':
        return fmt(tlib.rows(key + '-mode'), '`multi-1seg`', '`single`', field)
    if sec == 'Single against Multi':
        k, h = ('-mode', '`multi-1seg`') if n == 1 else ('-mode2', '`multi-2seg`')
        return fmt(tlib.rows(key + k), h, '`single`', field)
    if sec in ('SpinOrSleep<Futex> against SpinOnly', 'Futex against NoWake'):
        ha = '`-so`' if v4 else 'nothing'
        return fmt(tlib.rows(key + '-wake'), ha, f'`{sos}`', lambda l: f"..{l}-stfe-wtnone")
    if sec == 'What a wait costs':
        m = {'st1us-wtnone': 'st1us-wtnone-so', 'st1us-wtfe-sleep-futex': 'st1us-wtfe-slp-futex',
             'st0-wtfe-sleep-futex': 'st0-wtfe-slp-futex'}
        return fmt(tlib.rows('wait'), '`stfe-wtnone-so`', "the row's", lambda l: f"..2t-single-{m[l]}")
    if sec == 'v3 against v2':
        return fmt(tlib.rows('v2v3'), '`v2`', '`v3`', lambda l: l)
    raise SystemExit('no spec for ' + sec)

def retable(text, note):
    out = []; sec = ''; n = {}; intable = False
    for l in text.split('\n'):
        if l.startswith('#'):
            sec = l.lstrip('#').strip()
        if l.startswith('| host | bench'):
            n[sec] = n.get(sec, 0) + 1
            intable = True
            out += spec(note, sec, n[sec])
            if sec == 'v4 against v3':
                out += ['', '@@SECOND@@', ''] + spec(note, sec, 2)
            continue
        if intable:
            if l.startswith('|'):
                continue
            intable = False
        out.append(l)
    return '\n'.join(out)
EOF
