python3 - <<'EOF'
import sys; sys.path.insert(0,'tmp')
import retable, tlib
from retable import fmt, chk, base
T='spntfe-slpt0'
def spec(note, sec, n):
    v4 = note == 'v4'
    so, sos = ('so-', 'sos-futex-') if v4 else ('', 'futex-')
    key = 'v4' if v4 else 'v3'
    field = lambda lab: f"..{base(lab)}-*-{sos if chk(lab) else so}{T}"
    if sec == 'v4 against v3':
        r = tlib.rows('v3v4')
        if n == 1:
            return fmt(r, '`v3`, nothing', '`v4`, `-so`', lambda l: f"*-{l}*-{T}", lambda l: not chk(l))
        return fmt(r, '`v3`, `-futex`', '`v4`, `-sos-futex`', lambda l: f"*-{base(l)}*-{T}", chk)
    if sec == 'Multi over one segment against two':
        return fmt(tlib.rows(key + '-segs'), '`multi-2seg`', '`multi-1seg`', field)
    if sec == 'Single against Multi over one segment':
        return fmt(tlib.rows(key + '-mode'), '`multi-1seg`', '`single`', field)
    if sec == 'Single against Multi':
        k, h = ('-mode', '`multi-1seg`') if n == 1 else ('-mode2', '`multi-2seg`')
        return fmt(tlib.rows(key + k), h, '`single`', field)
    if sec == 'SpinOrSleep<Futex> against SpinOnly':
        return fmt(tlib.rows('v4-wake'), '`so`', '`sos-futex`', lambda l: f"..{l}-*-{T}")
    if sec == 'Futex against NoWake':
        return fmt(tlib.rows('v3-wake'), 'nothing', '`-futex`', lambda l: f"..{l}*-{T}")
    if sec == 'What a wait costs':
        m = {'st1us-wtnone': 'so-spnt1us-slpt0', 'st1us-wtfe-sleep-futex': 'slp-futex-spnt1us-slptfe',
             'st0-wtfe-sleep-futex': 'slp-futex-spnt0-slptfe'}
        return fmt(tlib.rows('wait'), '`so-spntfe-slpt0`', "the row's", lambda l: f"..2t-single-{m[l]}")
    if sec == 'v3 against v2':
        return fmt(tlib.rows('v2v3'), '`v2`', '`v3`', lambda l: l)
    raise SystemExit('no spec for ' + sec)
retable.spec = spec
def run(p, note, start=None):
    s=open(p).read(); i = s.index(start) if start else 0
    body=s[i:]
    # the second v3v4 table already exists now, so regenerate both by count
    out=[]; sec=''; n={}; intable=False
    for l in body.split('\n'):
        if l.startswith('#'): sec=l.lstrip('#').strip()
        if l.startswith('| host | bench'):
            n[sec]=n.get(sec,0)+1; intable=True; out+=spec(note,sec,n[sec]); continue
        if intable:
            if l.startswith('|'): continue
            intable=False
        out.append(l)
    open(p,'w').write(s[:i]+'\n'.join(out))
run('notes/mpsc-v4-mode-waits.md','v4')
run('notes/mpsc-v3-mode-wake.md','v3','## The measuring hosts')
EOF
for f in notes/mpsc-v4-mode-waits.md notes/mpsc-v3-mode-wake.md; do grep -A3 '^| host' $f | grep -v '^--\|^|---'; done | cut -c1-120; iiac-perf-dev --version >/dev/null; cargo run --release -q -- 2>/dev/null | grep -o 'zcr-mpsc-v[34]-[a-z0-9-]*' | sort -u

