/// elimination.
pub trait Bench {
    /// Human-readable name used in the report header.
    fn name(&self) -> &str;

    /// Run one unit of work. Return any value derived from the work
    /// to defeat DCE: the caller black-boxes it.
    fn step(&mut self) -> u64;
}

/// Runtime configuration for one [`run_adaptive`] call.
#[derive(Debug, Clone, Copy)]
pub struct RunCfg<'a> {
    /// Wall-clock seconds budget for time-based runs. Ignored when
    /// `samples_override` is set.
    pub target_seconds: f64,
    /// Force a fixed sample count, bypassing the time budget.
    pub samples_override: Option<u64>,
    /// Force a fixed inner-loop count, bypassing the
    /// micro-probe-driven auto-sizing.
    pub inner_override: Option<u64>,
    /// CPU pool for thread pinning, slot `i` for thread `i` via
    /// [`cpu_for`][RunCfg::cpu_for], a thread past its end
    /// unpinned. Empty means no pinning.
    pub pin_cpus: &'a [usize],
    /// The placement's name, a `[profiles]` entry or `unpinned`,
    /// `None` when the pool was given as CPUs.
    pub pin_name: Option<&'a str>,
    /// The bench's threads in pin order by role
    /// ([`crate::benches::Roles`]), which the record reads the pool
    /// against. Empty in a parent's config that serves several
    /// benches, where the record falls back to the pool.
    pub roles: &'a [&'static str],
    /// When set, [`crate::tprobe::TProbe::report`] emits raw TSC
    /// ticks instead of nanoseconds. Plumbed from the `-t/--ticks`
    /// CLI flag.
    pub report_ticks: bool,
    /// Sample the environment at every block seam, so the
    /// environment grade spans the whole run. Cleared by
    /// `--no-env-probe`, which leaves only the warmup probes.
    /// Plumbed from the CLI.
    pub seam_probes: bool,
    /// Band-label style for [`crate::report::print_report`] histogram rows.
    /// Plumbed from the `--band-labels` CLI flag.
    pub band_labels: BandLabels,
    /// Decimal digits on [`crate::report::print_report`] time columns. Plumbed
            .map(|b| (b.mean_ps / PS_PER_NS, b.count))
            .collect();
        let means: Vec<f64> = points.iter().map(|p| p.0).collect();
        let (ci95_ns, lsc_ns) = match crate::series::Series::of(&means) {
            Some(s) if replicated && means.len() >= crate::gauge::MIN_SERIES_POINTS => {
                (Some(s.ci95()), Some(s.lsc()))
            }
            _ => (None, None),
        };
        BlockStats {
            blocks: means.len() as u64,
            mean_ns: crate::series::weighted_mean(&points),
            ci95_ns,
            lsc_ns,
        }
    }
}

/// Everything a finished [`run_adaptive`] run produced: the
/// histogram plus the metadata [`crate::report::print_report`] needs and the
/// time-ordered [`BlockSummary`] series, one per block, the gauge reads.
#[derive(Debug)]
pub struct RunOutput {
    /// Per-call values (ps) of every sample.
    pub hist: Histogram<u64>,
    /// Samples taken, the header's `samples=`.
    pub samples: u64,
    /// Calls per sample (inner-loop count).
    pub inner: u64,
    /// Wall time of the run, seconds: block sleeps and warmups included.
    pub duration_s: f64,
    /// Seconds spent inside blocks recording samples, the part of
    /// `duration_s` the budget buys: the wall time less the sleeps
    /// and the per-block warmups.
    pub measured_s: f64,
    /// Seconds the system spent suspended during the run (see
    /// [`ClockPair`]). [`crate::report::print_report`] flags poisoned stats
    /// when non-trivial.
    pub suspended_s: f64,
    /// The block series' mean and what the series supports
    /// ([`BlockStats`]), read from [`RunOutput::blocks`].
    pub block_stats: BlockStats,
    /// Time-ordered summaries from the pipeline, one per block:
    /// the run's time axis and its replicates, the one series the
    /// gauge, the resolution curve, and the block stats read.
    pub blocks: Vec<BlockSummary>,
    /// Blocks the time cap ended before their sample count
    /// ([`BLOCK_TIME_CAP_MULT`]): zero when the sizing estimate
    /// held, and the report's cue that it did not.
    pub blocks_cut: u64,
    /// Time-ordered micro-probe summaries: the environment
    /// grade's input. One series, two stretches: see
    /// [`RunOutput::warmup_probes`].
    pub probes: Vec<ProbeSummary>,
    /// How many leading [`RunOutput::probes`] came from warmup.
    /// Splits the series into the stretch measured before the
    /// bench ran and the stretch measured alongside it, graded
    /// separately, because a ramp warmup absorbed is not a fault
    /// and blending the two invents a step at the boundary.
    pub warmup_probes: usize,
    /// How the warm stretch ended: the warm-until-stable exit verdict the report prints
    /// Delivered frequency (kHz) as the driver reports it.
    pub khz: u64,
}

/// Drive `bench` against `cfg` and return a [`RunOutput`].
///
/// After warming until stable (see [`warmup_and_probe`]), `inner` is auto-sized so apparatus
/// framing doesn't dominate (skipped when `cfg.inner_override` is set), and the block's sample
/// count is sized from the same warmup numbers ([`block_samples`]). The run is then
/// `cfg.blocks` blocks of that count ([`run_blocked`]), flowing through the [`BlockPipeline`],
/// so the output carries the run's time axis as one summary per block alongside the histogram.
pub fn run_adaptive<B: Bench>(bench: &mut B, cfg: &RunCfg) -> RunOutput {
    let warmed = warmup_and_probe(bench, cfg.settle_time_s, cfg.warm_cap_s);

    // The last warmup probe is the most-warmed one, so sizing reads a post-warmup
    // frame by construction, and the step cost is the exit window's best pass
    // ([`Warmed::step_cost_ns`]).
    let frame_ns = match warmed.probes.last() {
        Some(p) => (p.floor_q_ps as f64 / PS_PER_NS).max(1.0),
        None => 1.0,
    };
    let inner = cfg
        .inner_override
        .unwrap_or_else(|| pick_inner(warmed.step_cost_ns, frame_ns));
    // A sample is `inner` steps inside one timer frame, at the speed the warmup typically
    // held rather than its best.
    let count = block_samples(cfg, warmed.typical_cost_ns * inner as f64 + frame_ns);

    let Warmed {
        origin,
        probes: warm_probes,
        prober,
        exit: warm_exit,
        tail: warm_tail,
        clock: warm_clock,
        settle: warm_settle,
        clock_profile: warm_clock_profile,
        used_s: warm_used_s,
        budget_s: warm_budget_s,
        ..
    } = warmed;
    let warmup_probes = warm_probes.len();
    let mut pipeline = BlockPipeline::new(origin, prober, warm_probes, cfg.seam_probes);
    let wall_start = std::time::SystemTime::now();
    let clocks = ClockPair::now();
    let (duration_s, blocks_cut) = run_blocked(bench, &mut pipeline, count, inner, cfg);
    let (hist, blocks, probes, seam_clock) = pipeline.finish();
    let samples = hist.len();
    // Sleepless blocks are partitions of one run, not replicates
    // ([`BlockStats`]).
    let block_stats = BlockStats::from_blocks(&blocks, cfg.block_sleep_s.1 > 0.0);
    let measured_s = blocks.iter().map(|b| b.t_end_s - b.t_start_s).sum();
    let resolution = crate::resolution::from_blocks(&blocks);
    RunOutput {
        hist,
        samples,
        inner,
        duration_s,
        measured_s,
        suspended_s: clocks.suspended_s(),
        block_stats,
        blocks,
        blocks_cut,
        probes,
        warmup_probes,
        warm_exit,
        warm_tail,
        warm_clock,
        warm_settle,
        warm_clock_profile,
        warm_used_s,
        warm_budget_s,
        wall_start,
        seam_clock,
        resolution,
        counters: std::collections::BTreeMap::new(),
    }
}

/// Samples per block, sized once so every block runs the same
/// count and the block means are equal replicates whenever the
/// estimate holds. A time-budgeted block the cap ends early
/// ([`block_cap_s`]) holds fewer.
///
/// - A fixed `-s` count divides by the block count, rounded up,
///   so the run takes at least the count asked for and the
///   header's `samples=` reports what ran.
/// - A time budget gives each block its share of the seconds,
///   and the count is that share over `sample_cost_ns`, the
///   warmup's typical step cost times `inner` plus the timer
///   frame: an estimate, like the budget itself, and `duration=`
///   reports the measured wall time. At least one sample per
///   block, so a bench slower than the block's share still runs.
fn block_samples(cfg: &RunCfg, sample_cost_ns: f64) -> u64 {
    match cfg.samples_override {
        Some(samples) => samples.div_ceil(cfg.blocks).max(1),
        None => {
            let share_ns = cfg.target_seconds * 1e9 / cfg.blocks as f64;
            (share_ns / sample_cost_ns).floor().max(1.0) as u64
        }
    }
}

/// A block's time cap in seconds: [`BLOCK_TIME_CAP_MULT`] times its share of the budget.
/// `None` for a fixed `-s` count, which runs the count it asked for however long it takes.
fn block_cap_s(cfg: &RunCfg) -> Option<f64> {
    match cfg.samples_override {
        Some(_) => None,
        None => Some(BLOCK_TIME_CAP_MULT * cfg.target_seconds / cfg.blocks as f64),
    }
}

/// Run `cfg.blocks` measurement blocks of `count` samples each:
/// before each, sleep a uniform draw from the block sleep span
/// (re-rolls scheduler / frequency / mode-mix state, skipped at
/// zero) and step unrecorded for the block warmup (post-wake
/// ramp, skipped at zero), then measure. All samples land in the
/// pipeline, which summarizes each block at its seam, and the
/// summaries feed [`BlockStats`] once the run is over. A block
/// past its time cap ([`block_cap_s`]) stops early, the clock
/// read every [`CAP_CHECK_SAMPLES`] samples. Returns the wall
/// time, sleeps and warm-ups included, and how many blocks the
/// cap cut.
fn run_blocked<B: Bench>(
    bench: &mut B,
    pipeline: &mut BlockPipeline,
    count: u64,
    inner: u64,
    cfg: &RunCfg,
) -> (f64, u64) {
    let (sleep_s, warmup_s) = (cfg.block_sleep_s, cfg.block_warmup_s);
    let cap = block_cap_s(cfg).map(std::time::Duration::from_secs_f64);
    let mut cut = 0u64;
    let mut dither = Dither::new();
    let run_start = std::time::Instant::now();
    for _ in 0..cfg.blocks {
        if sleep_s.1 > 0.0 {
            std::thread::sleep(std::time::Duration::from_secs_f64(dither.span_s(sleep_s)));
        }
        if warmup_s > 0.0 {
            warm_loop(
                bench,
                WarmPass::Seconds {
                    s: warmup_s,
                    chunk: 1,
                },
                None,
                |_, n| n >= 1,
            );
        }
        // The block opens after the gap, so no block spans time
        // the bench wasn't running.
        pipeline.begin();
        let block_start = std::time::Instant::now();
        let mut done = 0u64;
        while done < count {
            let chunk = CAP_CHECK_SAMPLES.min(count - done);
            for _ in 0..chunk {
                record_sample(bench, inner, pipeline, &mut dither);
            }
            done += chunk;
            if done < count && cap.is_some_and(|c| block_start.elapsed() >= c) {
                cut += 1;
                break;
            }
        }
        pipeline.end();
    }
    (run_start.elapsed().as_nanos() as f64 / 1e9, cut)
}

