/// The block pipeline: samples land in a staging buffer, a full
/// stage drains into the open block's histogram and exact
/// accumulators, and the block's seam ([`BlockPipeline::end`])
/// summarizes the block for the gauge, merges its histogram into
/// the run's, and probes the box. Nothing flushes between seams,
/// and memory stays bounded at one stage plus two histograms
/// whatever the block's length.
struct BlockPipeline {
    /// Staged samples (ps) not yet drained into the block.
    stage: Vec<u64>,
    /// The run's histogram: every block merged in at its seam.
    hist: Histogram<u64>,
    /// The open block's histogram, the bounded structure its
    /// floor quantile and census are read from, reset at the
    /// seam.
    block: Histogram<u64>,
    /// Samples drained into the open block so far.
    count: u64,
    /// Their sum (ps), exact.
    sum_ps: u128,
    /// The open block's fastest sample (ps).
    floor_ps: u64,
    /// The open block's slowest sample (ps).
    max_ps: u64,
    summaries: Vec<BlockSummary>,
    run_start: std::time::Instant,
    block_start_s: f64,
    /// Micro-probe scratch, run once per non-empty seam.
    prober: Prober,
    /// The environment series: warmup probes, then one per block
    /// seam. Shares [`BlockSummary`]'s time origin, so the two
    /// series line up sample for sample on one axis.
    probes: Vec<ProbeSummary>,
    /// Whether to probe at each seam (`--no-env-probe` clears
    /// it, leaving the warmup stretch alone).
    seam_probes: bool,
    /// One delivered-clock sample per non-empty seam, on the same
    /// time axis as the summaries. Never gated by `seam_probes`:
    /// a single sysfs read is orders cheaper than the ~256 us
    /// micro-probe that gate exists for.
    seam_clock: Vec<SeamClock>,
}

impl BlockPipeline {
    /// Pipeline continuing an in-progress run: `origin` is the
    /// timestamp origin (the warmup start, so blocks and probes
    /// share one clock), and `probes` the warmup stretch of the
    /// environment series that `prober` keeps extending.
    fn new(
        origin: std::time::Instant,
        prober: Prober,
        probes: Vec<ProbeSummary>,
        seam_probes: bool,
    ) -> Self {
        let block_start_s = origin.elapsed().as_nanos() as f64 / 1e9;
        Self {
            stage: Vec::with_capacity(STAGE_SAMPLES),
            hist: new_hist(),
            block: new_hist(),
            count: 0,
            sum_ps: 0,
            floor_ps: u64::MAX,
            max_ps: 0,
            summaries: Vec::new(),
            run_start: origin,
            block_start_s,
            prober,
            probes,
            seam_probes,
            seam_clock: Vec::new(),
        }
    }

    /// Seconds since the pipeline was created.
    fn elapsed_s(&self) -> f64 {
        self.run_start.elapsed().as_nanos() as f64 / 1e9
    }

    /// Open a block: its start is now. Called after the block's
    /// sleep and warmup, so the gap is never inside a block.
    fn begin(&mut self) {
        self.block_start_s = self.elapsed_s();
    }

    /// Append one per-call sample (ps). Drains the stage into the
    /// block when it fills.
    fn push(&mut self, per_call_ps: u64) {
        self.stage.push(per_call_ps);
        if self.stage.len() >= STAGE_SAMPLES {
            self.drain();
        }
    }

    /// Move the staged samples into the open block's histogram
    /// and accumulators. Not a seam: no summary, probe, or clock
    /// read, only the memory bound doing its job.
    fn drain(&mut self) {
        for &v in &self.stage {
            self.block.saturating_record(v);
            self.floor_ps = self.floor_ps.min(v);
            self.max_ps = self.max_ps.max(v);
            self.sum_ps += u128::from(v);
        }
        self.count += self.stage.len() as u64;
        self.stage.clear();
    }

    /// Close the open block: drain the stage, summarize the block
    /// for the gauge, merge its histogram into the run's, and
    /// probe the box in the seam. A block that took no samples
    /// leaves nothing behind.
    fn end(&mut self) {
        self.drain();
        if self.count == 0 {
            return;
        }
        let t_end_s = self.elapsed_s();
        // The robust floor and the census come from the block's
        // histogram: an exact order statistic over a block of any
        // length would need every value kept, and the histogram's
        // 0.1% is below what the gauge's thresholds resolve.
        let floor_q_ps = self.block.value_at_quantile(BLOCK_FLOOR_Q).max(1);
        let over_cut = over_floor_cut(floor_q_ps, BLOCK_OVER_ADD_PS);
        let over_floor = self
            .block
            .count_between(over_cut.saturating_add(1), u64::MAX);
        self.summaries.push(BlockSummary {
            t_start_s: self.block_start_s,
            t_end_s,
            count: self.count,
            floor_ps: self.floor_ps,
            floor_q_ps,
            mean_ps: self.sum_ps as f64 / self.count as f64,
            max_ps: self.max_ps,
            over_floor,
        });
        self.hist
            .add(&self.block)
            .expect("the block and run histograms share new_hist()'s bounds"); // OK: same bounds, so every recorded value fits
        self.block.reset();
        self.count = 0;
        self.sum_ps = 0;
        self.floor_ps = u64::MAX;
        self.max_ps = 0;
        // The seam's delivered-clock read, ahead of the probe so
        // it lands as close to the block it caps as possible.
        if let Some(f) = crate::freq::avg_freq() {
            self.seam_clock.push(SeamClock {
                t_ns: self.run_start.elapsed().as_nanos() as u64,
                cpu: f.cpu,
                khz: f.khz,
            });
        }
        // Probe the box in the seam the summary already opened:
        // the bench is stopped either way, so the environment
        // series gets the run's whole time span for a fraction of
        // a gap that exists regardless.
        if self.seam_probes {
            self.probes.push(self.prober.probe(self.run_start));
        }
    }

    /// Close any open block and yield the histogram, the block
    /// summaries, the environment probe series, and the seam
    /// clock series.
    #[allow(clippy::type_complexity)]
    // OK: a one-consumer private seam. Naming a struct for it would outlive its use.
    fn finish(
        mut self,
    ) -> (
        Histogram<u64>,
        Vec<BlockSummary>,
        Vec<ProbeSummary>,
        Vec<SeamClock>,
    ) {
        self.end();
        (self.hist, self.summaries, self.probes, self.seam_clock)
    }
}

/// Time one sample (`inner` back-to-back calls), divide down to a
/// per-call value in **picoseconds**, and record it, clamping at
/// the histogram bounds, since a suspend-inflated or wedged sample
/// must not panic a long run ([`crate::report::warn_invalid`] flags it instead).
///
/// - The seam dither (a random sub-quantum spin before the timer
///   pair, outside the timed interval) stops the run's aggregate
///   means from carrying a coherent ±quantum phase bias, up to
///   ~±2% on fast benches (see
///   notes/design.md#dithering-random-phase-injection).
fn record_sample<B: Bench>(
    bench: &mut B,
    inner: u64,
    pipeline: &mut BlockPipeline,
    dither: &mut Dither,
) {
    dither.spin();
    let start = std::time::Instant::now();
    for _ in 0..inner {
        black_box(bench.step());
    }
    let elapsed_ps = start.elapsed().as_nanos().saturating_mul(1000);
    pipeline.push(round_elapsed_ps(elapsed_ps, inner));
}

/// Per-call value: `elapsed_ps / inner`, rounded to nearest, in
/// u128 so an hours-long suspend-inflated sample can't overflow
/// the ×1000 ns->ps conversion. The cast clamps at u64::MAX and
/// `saturating_record` clamps again at the histogram bound.
fn round_elapsed_ps(elapsed_ps: u128, inner: u64) -> u64 {
    let inner = inner as u128;
    ((elapsed_ps + inner / 2) / inner).min(u64::MAX as u128) as u64
}

/// Paired run-start readings of `CLOCK_MONOTONIC` and
/// `CLOCK_BOOTTIME`, for detecting a system suspend that spanned
/// a measurement run.
//! Sub-quantum phase dither for the sample seam.
//!
//! The timer reads integer nanoseconds, so a sample's error depends
//! on where it happens to land on the clock lattice. Spinning a
//! random, sub-quantum amount *outside* the timed interval before
//! each sample re-rolls that phase, which makes the quantization
//! error zero-mean across a run instead of a coherent bias.
//!
//! - [`Dither::spin`] is the seam call: run between samples, never
//!   inside a measured interval.
//! - [`Dither::span_s`] draws from a time span for callers wanting
//!   coarser randomness, the block sleep and run sleep lengths.
//!
//! See notes/design.md#dithering-random-phase-injection for why
//! random phase beats a fixed offset.

use std::hint::black_box;

/// Dither span in neutral spin iterations (~0.4-0.5 ns each, so
/// ~26-32 ns, spanning ~3 clock quanta). A random 0..span delay
/// before each sample randomizes its phase on the ~10 ns clock
/// lattice, making the quantization error zero-mean.
pub const DITHER_SPAN: u64 = 64;

/// Xorshift64* PRNG for dither lengths. No external dep, since phase
/// randomization needs rough uniformity, not statistical rigor.
struct XorShift64(u64);

impl XorShift64 {
    /// Next pseudo-random u64.
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
}

/// Sub-quantum phase dither: a random 0..[`DITHER_SPAN`] neutral
/// spin, run *outside* the timed interval before each sample.
pub struct Dither(XorShift64);

impl Dither {
    /// New dither source, seeded from wall-clock nanos (any
    /// per-invocation variation suffices for phase dither).
    pub fn new() -> Self {
        let seed = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.subsec_nanos() as u64 | 1)
            .unwrap_or(0x9E37_79B9_7F4A_7C15); // OK: fixed fallback seed still dithers
        Dither(XorShift64(seed))
    }

    /// Spin a random 0..[`DITHER_SPAN`] iterations to re-roll the
    /// next sample's phase on the clock lattice.
    #[inline]
    pub fn spin(&mut self) {
        let r = self.0.next() % DITHER_SPAN;
        for _ in 0..r {
            black_box(1u64);
        }
    }

    /// Next raw pseudo-random u64, behind [`Dither::span_s`].
    fn rand_u64(&mut self) -> u64 {
        self.0.next()
    }

    /// A uniform draw from a `(min_s, max_s)` span, seconds: the span itself when its ends
    /// agree, so a fixed sleep stays fixed. What block sleeps and run sleeps both re-roll by.
    pub fn span_s(&mut self, (lo, hi): (f64, f64)) -> f64 {
        let frac = self.rand_u64() as f64 / u64::MAX as f64;
        lo + frac * (hi - lo)
    }
}

impl Default for Dither {
    /// Same as [`Dither::new`].
    fn default() -> Self {
        Self::new()
    }
}

