ORDER = ["smt", "ccx", "x-ccx", "x-ccd", "unpinned"]
SHAPES = ["multi-2seg", "multi-1seg", "single"]
FILES = {
    "first": ("records/mpsc-v4-{h}.jsonl", "old"),
    "five": ("tmp/session-{h}-20261008/mpsc-v4-{h}-20261008.jsonl", "new"),
    "fifty": ("tmp/session-{h}-20261008/mpsc-v4-{h}-20261008-runs50.jsonl", "new"),
}


def name(scheme, ver, t, shape, sleeps):
    """A spin-forever bench's registry name, in the old or the new naming."""
    if scheme == "old":
        tail = "" if not sleeps else ("-futex" if ver == "v3" else "-spinorsleep-futex")
        return f"zcr-mpsc-{ver}-{t}-{shape}-stfe-wtnone{tail}"
    if ver == "v3":
        return f"zcr-mpsc-v3-{t}-{shape}{'-futex' if sleeps else ''}-spntfe"
    return f"zcr-mpsc-v4-{t}-{shape}-{'sos-futex' if sleeps else 'so'}-spntfe"


WAIT = {
    "old": ["st1us-wtnone", "st1us-wtfe-sleep-futex", "st0-wtfe-sleep-futex"],
    "new": ["so-spnt1us", "slp-futex-spnt1us-slptfe", "slp-futex-slptfe"],
}


def groups(s):
    """Every comparison as (group, label, bench A, bench B), labels in the new words."""
    g = []
    for t in ("1t", "2t"):
        g.append(("v2v3", t, f"zcr-mpsc-v2-{t}", name(s, "v3", t, "multi-2seg", False)))
    for ver in ("v3", "v4"):
        for t in ("1t", "2t"):
            for sl in (False, True):
                w = "sleeps" if sl else "spins"
                n = lambda shape: name(s, ver, t, shape, sl)
                g.append((f"{ver}-segs", f"{t} {w}", n("multi-2seg"), n("multi-1seg")))
                g.append((f"{ver}-mode1", f"{t} {w}", n("multi-1seg"), n("single")))
                g.append((f"{ver}-mode2", f"{t} {w}", n("multi-2seg"), n("single")))
            for shape in SHAPES:
                g.append((f"{ver}-wake", f"{t}-{shape}", name(s, ver, t, shape, False), name(s, ver, t, shape, True)))
    for sl in (False, True):
        for t in ("1t", "2t"):
            for shape in SHAPES:
                w = "sleeps" if sl else "spins"
                g.append(("v3v4", f"{t}-{shape} {w}", name(s, "v3", t, shape, sl), name(s, "v4", t, shape, sl)))
    base = name(s, "v4", "2t", "single", False)
    for old, new in zip(WAIT["old"], WAIT["new"]):
        g.append(("wait", new, base, f"zcr-mpsc-v4-2t-single-{old if s == 'old' else new}"))
    return g


ROW = re.compile(
    r"^(\S+)\s+(\S+) -> (\S+)\s+(\d+\.\d{3})\s+(\d+\.\d{3})\s*(-?[\d.]+)\s+([\d.]+)\s+([\d.]+)\s+(.*?)\s{2,}(.*)$"
)


def analyze(session, host, gs, part):
    path, _ = FILES[session]
    cmd = ["iiac-perf", "analyze", path.format(h=host), "--by", "placement"]
    for _, _, a, b in gs:
        cmd += ["--compare", f"bench={a},{b}"]
    out = subprocess.run(cmd, check=True, capture_output=True, text=True).stdout
    open(f"tmp/cmp3-raw-{session}-{host}-{part}.txt", "w").write(out)
    legend = re.findall(r"^(\S+) = bench (\S+)$", out, re.M)
    letters = dict(legend)
    if len(letters) != len(legend):
        raise SystemExit(f"letters collide: {session} {host} {part}")
    rows = {}
    for line in out.splitlines():
        m = ROW.match(line)
        if m and m.group(2) in letters:
            pl, la, lb, a, b, d, claim, _, pairing, verdict = m.groups()
            rows[(letters[la], letters[lb], pl)] = dict(
                a=float(a), b=float(b), d=float(d), claim=float(claim), pairing=pairing,
                seen=verdict.split(",")[0] == "detected", verdict=verdict)
    res = {}
    for grp, label, a, b in gs:
        for pl in ORDER:
            r = rows.get((a, b, pl))
            if r:
                res[(grp, label, pl)] = r
    if len(res) != len(rows):
        print(f"MISMATCH {session} {host} {part}: {len(res)} of {len(rows)}", file=sys.stderr)
    return res


def load(session, host):
    """analyze letters wrap after Z, so the wait group runs on its own."""
    gs = groups(FILES[session][1])
    res = analyze(session, host, [g for g in gs if g[0] != "wait"], "main")
    res.update(analyze(session, host, [g for g in gs if g[0] == "wait"], "wait"))
    return res


def main():
    data = {}
    for h in HOSTS:
        for s in FILES:
            data[f"{s}|{h}"] = {"|".join(k): v for k, v in load(s, h).items()}
            print(s, h, len(data[f"{s}|{h}"]), file=sys.stderr)
    json.dump(data, open("tmp/cmp3.json", "w"), indent=0)


main()

